"""Build a new manuscript source from verified updated measurements."""
from pathlib import Path
import json,re,shutil
ROOT=Path(__file__).resolve().parents[1]
OLD=ROOT/'articulo_boletin_geologia_uis';OUT=ROOT/'articulo_boletin_geologia_uis_adjunto'
RUN=ROOT/'resultados/tomografia_1d_adjunto_consistente_2026-10-10'
def fmt(x,n=4):return f'{x:.{n}f}'.replace('.',',')
def main():
    assert (OUT/'fuentes/metricas_articulo_auditadas.json').exists()
    old=json.loads((OLD/'fuentes/metricas_articulo_auditadas.json').read_text())
    m=json.loads((OUT/'fuentes/metricas_articulo_auditadas.json').read_text())
    source=(OLD/'crear_manuscrito.py').read_text(encoding='utf-8')
    dest=OUT/'crear_manuscrito_adjunto.py';assert not dest.exists()
    initial=m['initial_holdout_RMS_s'];final=m['final_holdout_RMS_s'];delta=final-initial;percent=100*delta/initial
    trainred=100*(1-m['final_train_RMS_s']/m['initial_train_RMS_s'])
    ci=m['holdout_delta_ci95_s'];diag=m['final_ray_diagnostic']
    fd=json.loads((RUN/'finite_difference_updated_model.json').read_text())
    max_fd=max(x['relative_l2_directional_error'] for x in fd['independent_real_model_fd_checks'])
    improving=delta<0;direction='disminución' if improving else 'aumento'
    def paragraph(start,new):
        nonlocal source
        a=source.index(start);candidates=[source.find(t,a) for t in ['\n\n',"''')"]];b=min(x for x in candidates if x>=0)
        source=source[:a]+new+source[b:]
    paragraph('Los resultados temporales se presentan en la Tabla 3.',f'Los resultados temporales se presentan en la Tabla 3. El RMS de entrenamiento disminuyó un {fmt(trainred,1)} %, pero ese ajuste incluye la relocalización y los términos de estación, además de Vp. El cambio en reserva fue de {fmt(delta)} s, equivalente a una {direction} del {fmt(abs(percent),2)} %. El intervalo pareado del 95 % fue [{fmt(ci[0])}; {fmt(ci[1])}] s. '+('El intervalo percentil no cruza cero bajo el esquema de remuestreo utilizado. ' if ci[0]*ci[1]>0 else 'El intervalo percentil incluye cero bajo el esquema de remuestreo utilizado. ')+('El modelo final mejora la predicción respecto al perfil transferido. ' if improving else 'El modelo final no mejora la predicción respecto al perfil transferido. ')+'La consistencia del núcleo se evalúa por separado del ajuste observado y de la resolución estructural. El remuestreo no cuantifica incertidumbre sistemática del modelo de referencia, del solucionador o de la selección del catálogo.')
    dv=m['final_active_dvp_percentiles'];v=m['final_active_vp_range_km_s'];st=m['static_range_s']
    paragraph('La máscara calculada con los rayos finales contiene',f"La máscara calculada con las sensibilidades finales contiene {m['active_cells']} celdas activas, de las cuales {m['active_cells_ge40']} están a profundidades iguales o mayores de 40 km. Las velocidades evaluadas en esas celdas abarcan {fmt(v[0])}–{fmt(v[1])} km/s. Respecto al perfil inicial, los percentiles 5 y 95 de perturbación son {fmt(dv[1],2)} % y {fmt(dv[3],2)} %; la mediana es {fmt(dv[2],2)} %. Los valores extremos alcanzan {fmt(dv[0],2)} % y {fmt(dv[4],2)} %. La presencia de valores en la cota superior exige considerar la dependencia de los límites impuestos. Los términos de estación finales oscilan entre {fmt(st[0])} y {fmt(st[1])} s.")
    paragraph('El patrón alternante lineal obtuvo una correlación',f"El patrón alternante lineal obtuvo una correlación de {fmt(m['linear_resolution']['correlation'])} y un error L2 relativo de {fmt(m['linear_resolution']['relative_l2_error'])}. La suma de las sensibilidades discretas ponderadas por la lentitud reproduce los tiempos del campo: el percentil 95 del desajuste absoluto es de {diag['kernel_time_minus_field_p95_abs_s']:.2e} s y el máximo es de {diag['kernel_time_minus_field_max_abs_s']:.2e} s. Esta identidad se evalúa antes de enmascarar las celdas y no se fuerza mediante normalización de los núcleos. Las pruebas independientes de diferencias finitas sobre campos completos del modelo real obtuvieron un error relativo máximo de 2,63 × 10⁻⁷. La concordancia confirma la consistencia del operador discreto, no la precisión de una solución continua ni la resolución de las placas.")
    paragraph('La discrepancia entre integral de rayos y campo eikonal es una limitación central:', 'Las sensibilidades se obtuvieron mediante diferenciación del esquema Godunov que produce el campo de tiempos. La identidad entre el tiempo del campo y la suma de sensibilidades ponderadas por lentitud, junto con las perturbaciones independientes del cálculo directo, comprueba la consistencia interna de la actualización. Se conserva una distinción entre esta concordancia y la precisión física de la malla de primer orden. El patrón alternante reutiliza el operador lineal y su recuperación no sustituye pruebas no lineales con un operador independiente, según los criterios de Rawlinson y Spakman (2016).')
    paragraph('El uso de 10 km para el cálculo directo,', 'El uso de 10 km para el cálculo directo, la ausencia de elevaciones y curvatura, la incertidumbre uniforme de 1 s y los límites de Vp pueden introducir sesgos que no quedan capturados por el remuestreo. La referencia del Valle Medio del Magdalena tampoco representa necesariamente la heterogeneidad crustal del Pacífico, el Cauca o la región caribeña. Se requiere evaluar un modelo mínimo 1D apropiado al dominio (Kissling et al., 1994), convergencia del cálculo directo al refinar la malla y sensibilidad a los pesos de regularización. Las derivadas ya verificadas permiten realizar esos contrastes sin mezclar la sensibilidad de un trazado geométrico con la de un campo discretizado. Tales contrastes de precisión espacial todavía no forman parte de los resultados presentados.')
    paragraph('La máscara final contiene 3465 celdas activas. Los cortes', f"La máscara final contiene {m['active_cells']} celdas activas. Los cortes inicial–final permiten observar variaciones laterales en las zonas cubiertas, pero el número de contribuciones significativas de sensibilidad no sustituye una evaluación independiente de resolución. La discrepancia entre el operador de sensibilidad y el campo de tiempos queda corregida a precisión numérica mediante diferenciación del mismo esquema eikonal. La precisión espacial de primer orden y la interpretación tectónica continúan requiriendo validación adicional.")
    source=source.replace('la discrepancia entre la integración por rayos y el campo de tiempos evidencia una limitación numérica pendiente.','la consistencia entre sensibilidades y campos se verifica a precisión numérica, mientras que la resolución espacial permanece condicionada por la malla.')
    source=source.replace('A discrepancy between ray integrated times and the travel time field further identifies an unresolved numerical limitation.','Discrete sensitivities reproduce field travel times to numerical precision and agree with independently recomputed finite differences; spatial accuracy remains limited by the first order grid.')
    source=source.replace('La propagación se calculó en coordenadas cartesianas locales,','La propagación se calculó en coordenadas cartesianas locales,')
    source=source.replace('Se utilizó C++ para evaluar candidatos de relocalización y construir longitudes de los rayos;','Se utilizó C++ para evaluar candidatos de relocalización y propagar las sensibilidades discretas;')
    source=source.replace('El retrotrazado de rayos utiliza una vecindad de 26 nodos para construir un núcleo aproximado de sensibilidad a la lentitud. Las celdas se actualizan si reciben al menos 20 contribuciones de rayos; esta máscara describe cobertura del operador y no resolución independiente.', 'La sensibilidad a lentitud se obtuvo mediante diferenciación inversa del esquema eikonal de primer orden. Para cada nodo se seleccionan los vecinos causales utilizados por el operador Godunov y se propagan sus derivadas en orden decreciente de tiempo; las contribuciones locales se acumulan sobre la parametrización de 20 km. El cálculo no utiliza un recorrido geométrico ni normalización posterior de sus longitudes. Este enfoque sigue el principio de coherencia entre discretización directa y adjunta descrito por Zunino et al. (2025), aplicado aquí al solucionador de primer orden de Zhao (2005). Las celdas se actualizan si reciben al menos 20 contribuciones con sensibilidad equivalente no menor de 0,1 km, umbral fijado como el 1 % del espaciamiento directo. El umbral se aplica solo al indicador de cobertura; no recorta las derivadas empleadas en la inversión ni en sus pruebas. La máscara no representa resolución independiente.')
    source=source.replace('Se ejecutó también un patrón alternante lineal de bloques de 40 km, con ruido de 0,03 s y el mismo operador de rayos fijo en generación e inversión. Este ensayo describe recuperación condicionada al operador. Por separado se contrastó la integral temporal de los rayos con los tiempos del campo eikonal para cuantificar su consistencia, requisito previo para interpretar los núcleos como derivadas adecuadas del problema directo.', 'Se ejecutó un patrón alternante lineal de bloques de 40 km, con ruido de 0,03 s y el mismo Jacobiano fijo en generación e inversión. Este ensayo describe recuperación condicionada al operador. Se verificó además la identidad de homogeneidad del operador, sumando sus derivadas respecto a lentitud ponderadas por la lentitud del modelo en la malla directa. La suma debe coincidir con el tiempo eikonal de cada observación. Se realizaron pruebas independientes mediante diferencias centrales en cuatro direcciones de un modelo sintético heterogéneo y seis direcciones del modelo real, estas últimas distribuidas en tres estaciones y doce eventos por estación. Los campos completos se recalcularon para las perturbaciones positivas y negativas; no se generaron datos de prueba con el Jacobiano evaluado. El programa rechaza campos que no satisfacen el residual local de la ecuación eikonal dentro de una tolerancia relativa de 2 × 10⁻⁷.')
    source=source.replace('La máscara calculada con los rayos finales contiene','La máscara calculada con las sensibilidades finales contiene')
    source=source.replace('Final ray coverage activated','Final discrete sensitivity coverage activated')
    source=source.replace('brecha azimutal de catálogo no mayor de 180°','brecha azimutal recalculada no mayor de 180°')
    source=source.replace('El resultado final mejora modestamente la predicción respecto al perfil transferido, pero el intervalo de remuestreo solo evalúa variación dentro de la muestra reservada.', ('El resultado final mejora la predicción respecto al perfil transferido' if improving else 'El resultado final aumenta el RMS de reserva respecto al perfil transferido')+', y el intervalo de remuestreo solo evalúa variación dentro de la muestra reservada.')
    source=source.replace('Esta mejora del 1,98 % caracteriza el desempeño predictivo del experimento',f'Esta {direction} del {fmt(abs(percent),2)} % caracteriza el desempeño predictivo del experimento')
    source=source.replace('Su principal aporte es una comparación reproducible desde 1D y una representación explícita de los vacíos que deben abordarse con cobertura y validación numérica adicionales.','Su principal aporte es una comparación reproducible desde 1D con sensibilidades numéricamente consistentes y una representación explícita de los vacíos que deben abordarse con cobertura y pruebas de resolución adicionales.')
    # Replace measured literals throughout abstracts, tables and narrative.
    numeric={}
    for key in ['final_train_RMS_s','final_holdout_RMS_s']:
        numeric[fmt(old[key])]=fmt(m[key]);numeric[f'{old[key]:.4f}']=f'{m[key]:.4f}'
    numeric.update({'−0,0327':fmt(delta),'−0.0642':f'{ci[0]:.4f}','−0.0021':f'{ci[1]:.4f}','−0,0642':fmt(ci[0]),'−0,0021':fmt(ci[1]),'1,98':fmt(abs(percent),2),'47,9':fmt(trainred,1)})
    for key in ['active_cells','active_cells_ge40','fragment_triangles']:numeric[str(old[key])]=str(m[key])
    numeric[fmt(old['final_active_vp_range_km_s'][0])]=fmt(m['final_active_vp_range_km_s'][0])
    for i,n in [(0,2),(1,2),(3,2),(4,2)]:numeric[fmt(old['final_active_dvp_percentiles'][i],n)]=fmt(m['final_active_dvp_percentiles'][i],n)
    for i in [0,1]:numeric[fmt(old['static_range_s'][i])]=fmt(m['static_range_s'][i])
    for a,b in zip(old['geometry'],m['geometry']):
        for key in ['events','control_cells','supported_faces','interpolated_faces']:numeric[str(a[key])]=str(b[key])
        for key in ['fit_benioff_rms_km','fit_benioff_p90_abs_km']:
            numeric[fmt(a[key],2)]=fmt(b[key],2);numeric[f'{a[key]:.2f}']=f'{b[key]:.2f}'
        numeric[fmt(100*a['interpolated_faces']/a['faces'],2)]=fmt(100*b['interpolated_faces']/b['faces'],2)
    # Simultaneous substitutions avoid accidental replacement of new values.
    pattern=re.compile(r'(?<![0-9])('+ '|'.join(re.escape(x) for x in sorted(numeric,key=len,reverse=True)) +r')(?![0-9])')
    source=pattern.sub(lambda a:numeric[a.group()],source)
    source=source.replace('las proporciones interpoladas de','las proporciones interpoladas de')
    source=source.replace('2,63 × 10⁻⁷',f'{max_fd:.2e}'.replace('.',','))
    source=source.replace('lookup={r[\'DOI\'].lower():r for r in REFS}',"REFS.append(json.loads((OUT/'fuentes/zunino_2025_crossref.json').read_text(encoding='utf-8-sig'))['message'])\nDOIS.append('10.1093/gji/ggaf283')\nlookup={r['DOI'].lower():r for r in REFS}")
    source=source.replace("'Manuscrito_tomografia_Vp_Colombia_UIS.docx'","'Manuscrito_tomografia_Vp_Colombia_UIS_adjunto_consistente.docx'")
    # Update English confidence interval already handled, and use neutral outcome.
    source=source.replace('The 95% confidence interval for final minus initial held out RMS was', 'The 95% confidence interval for final minus initial held out RMS was')
    source=source.replace('la predicción de eventos reservados y qué proporción','la predicción de eventos reservados y qué proporción')
    shutil.copy2(RUN/'zunino_2025_crossref.json',OUT/'fuentes/zunino_2025_crossref.json')
    dest.write_text(source,encoding='utf-8');print(dest)
if __name__=='__main__':main()
